  "动画修改已应用到原文草稿；尚未保存。": "アニメーション変更を原文の下書きに適用しました。まだ保存されていません。",
  "动画修改已应用；文本与已保存版本一致。": "アニメーション変更を適用しました。テキストは保存済みの内容と一致しています。",
  "动画控制记录": "アニメーション操作履歴",
  "只读显示动画命令执行时的状态和播放头，不代表当前画面。切换场景时保留记录，重新运行后清空。": "アニメーション操作を実行した時点の状態と再生位置を読み取り専用で表示します。現在の画面は示しません。履歴はシーンを切り替えても保持され、再実行するとリセットされます。",
  "按场景或动画标识筛选": "シーン ID またはアニメーション ID で絞り込む",
  "正在打开动画控制来源…": "アニメーション操作の参照元を開いています…",
  "无法打开动画控制来源，请返回编辑器查找该文档。": "アニメーション操作の参照元を開けません。エディターで該当文書を探してください。",
  "命令序号 {0} · 显示 {1} / {2} 条动画命令": "操作番号 {0} · {2} 件中 {1} 件のアニメーション操作を表示",
  "没有匹配的动画命令。": "一致するアニメーション操作はありません。",
  "当前没有已执行的动画命令。": "まだアニメーション操作は実行されていません。",
  "已执行暂停命令": "一時停止操作を実行済み",
  "已执行跳转命令": "再生位置の変更を実行済み",
  "场景 {0} · 动画 {1}": "シーン {0} · アニメーション {1}",
  "执行后状态：{0} · 播放头 {1} 秒": "実行後の状態：{0} · 再生位置 {1} 秒",
  "动画声明：{0} · {1}": "アニメーション宣言：{0} · {1}",
  "打开动画声明": "アニメーション宣言を開く",
  "暂停": "一時停止",
  "结束": "終了",
  "命名动画片段": "名前付きアニメーションクリップ",
  "添加动画片段": "アニメーションクリップを追加",
  "片段复用现有轨道，只指定原时间轴的区间。行为按稳定编号选择；更名不会改变编号，删除后原引用将失效。": "クリップは既存のトラックを共有し、元の時間軸の範囲を指定します。ビヘイビアは固定 ID で選択します。名前を変更しても ID は変わりませんが、削除すると参照が無効になります。",
  "片段 {0} / 32": "クリップ {0} / 32",
  "动画片段 {0}": "アニメーションクリップ {0}",
  "片段名称": "クリップ名",
  "片段开始（秒）": "クリップ開始（秒）",
  "片段结束（秒）": "クリップ終了（秒）",
  "片段循环": "クリップをループ",
  "移除动画片段": "アニメーションクリップを削除",
  "无法生成动画片段编号，请重试。": "アニメーションクリップの ID を生成できません。再試行してください。",
  "预览动画片段": "アニメーションクリップをプレビュー",
  "按场景、动画或片段筛选": "シーン、アニメーション、クリップで絞り込み",
  "已执行选择片段命令": "クリップ選択コマンドを実行しました",
  "片段：{0} · {1} · 原时间轴 {2}–{3} 秒": "クリップ：{0} · {1} · 元のタイムライン {2}～{3} 秒",
  "打开动画片段声明": "クリップの定義を開く",
  "完整动画": "アニメーション全体",
  "原时间轴 {0}–{1} 秒 · 片段时间从 0 开始": "元の時間軸 {0}–{1} 秒 · クリップの時間は 0 から開始",
  "Godot / 命名动画片段": "Godot / 名前付きアニメーションクリップ",
  "填写当前场景的动画片段 UUID，选择后从片段起点播放。clip_id 留空时选择完整动画。仅支持动画片段的场景组装项目生效；更名不影响编号引用。": "現在のシーンのアニメーションクリップの UUID を指定すると、選択して先頭から再生します。clip_id を空にするとアニメーション全体を選択します。クリップ対応の組み立て済みプロジェクトでのみ有効です。名前を変更しても ID による参照は維持されます。",
  "Godot / 项目动画控制": "Godot / プロジェクトのアニメーション制御",
  "在场景组装项目中控制当前场景的整份动画。command 可选 play、pause、stop、seek；seek 使用 time_seconds 并暂停，play 在末尾重新播放。单场景运行时不控制动画。": "シーンを組み立てたプロジェクトで、現在のシーンのアニメーション全体を操作します。command は play、pause、stop、seek から選択します。seek は time_seconds の位置に移動して一時停止し、末尾で play を呼ぶと最初から再生します。単一シーンの実行ではアニメーションを操作しません。",
  "Godot / 事件声音": "Godot / イベント音声",
  "填写已声明的音轨 UUID；订阅 sound 后，true 请求播放、false 请求停止。仅当前项目场景访问生效，也可在行为中直接调用声音接口。": "宣言済み音声トラックの UUID を指定します。sound を購読し、true で再生、false で停止を要求します。現在のプロジェクトのシーン訪問中のみ有効です。ビヘイビアから音声 API を直接呼び出すこともできます。",
  "声音控制记录": "音声操作履歴",
  "只读显示实际执行的声音命令，不代表当前播放状态或可听见的声音。切换场景时保留记录，重新运行后清空。": "実行済みの音声操作を読み取り専用で表示します。現在の再生状態や実際に聞こえる音を示すものではありません。履歴はシーンを切り替えても保持され、再実行するとリセットされます。",
  "按音轨或资源标识筛选": "トラック ID またはリソース ID で絞り込む",
  "正在打开声音控制来源…": "音声操作の参照元を開いています…",
  "无法打开声音控制来源，请返回编辑器查找该文档。": "音声操作の参照元を開けません。エディターで該当文書を探してください。",
  "命令序号 {0} · 显示 {1} / {2} 条声音命令": "操作番号 {0} · {2} 件中 {1} 件の音声操作を表示",
  "没有匹配的声音命令。": "一致する音声操作はありません。",
  "当前没有已执行的声音命令。": "まだ音声操作は実行されていません。",
