  "打开控制来源": "操作元を開く",
  "打开音轨声明": "トラック宣言を開く",
  "项目事件记录": "プロジェクトイベント履歴",
  "只读查看本次运行的事件发布和处理记录。切换场景时保留记录，重新运行后清空；此处不会发布事件。": "今回の実行のイベント発行と処理履歴を読み取り専用で表示します。シーンを切り替えても履歴は保持され、再実行するとリセットされます。この画面からイベントは発行しません。",
