  "订阅 checkpoint 并延迟发布一个值；接收后写入 last_event。仅项目运行生效，离开场景后撤销订阅。": "checkpoint を購読して後から値を発行し、受信後に last_event に書き込みます。プロジェクト実行時のみ有効で、シーンを離れると購読は解除されます。",
  "会话共享状态": "セッション共有状態",
  "只读查看本次项目运行的共享状态。切换场景时保留，重新运行后清空；此处不会修改游戏状态。": "今回のプロジェクト実行の共有状態を読み取り専用で表示します。シーンを切り替えても保持され、再実行するとリセットされます。この画面ではゲーム状態を変更しません。",
