  "最后来源：第 {0} 次访问 · {1}": "最後の変更元：訪問 {0} 回目 · {1}",
  "打开状态来源": "状態の変更元を開く",
  "无法打开状态来源，请返回编辑器查找该文档。": "状態の変更元を開けません。エディターで該当文書を探してください。",
  "Godot / 共享状态": "Godot / 共有状態",
  "在当前项目运行中累加 visit_count；状态跨场景保留，重新运行后清空。单场景运行时不写入。": "現在のプロジェクト実行で visit_count を加算します。状態はシーン間で保持され、再実行するとリセットされます。単一シーンの実行では書き込みません。",
  "Godot / 场景切换": "Godot / シーン切り替え",
  "在组装运行中请求切换到 target_scene_id 指定的成员场景；请在行为参数中填写目标场景标识。单场景运行时不切换。": "プロジェクト構成の実行中に、target_scene_id で指定した構成シーンへの切り替えを要求します。動作パラメーターに移動先のシーン ID を設定してください。単一シーンの実行では切り替わりません。",
  "运行对象来自当前场景；访问记录仅记录本次运行，不会切换编辑内容。": "実行オブジェクトは現在のシーンのものです。今回の実行の訪問記録で編集中の文書が切り替わることはありません。",
  "等待场景进入；旧场景的位置样本已清空。": "シーンへの移動を待っています。前のシーンの位置サンプルは消去済みです。",
