  "当前作者会话已变化，请返回后重新打开组装。": "編集セッションが変わりました。戻ってから構成を開き直してください。",
  "组装保存结果尚未确认。请重新读取工程核对，勿重复保存。": "構成の保存結果を確認できません。再度保存せず、プロジェクトを読み直して確認してください。",
  "正在处理项目组装…": "プロジェクト構成を処理中…",
  "组装已载入，可调整成员与启动场景。": "構成を読み込みました。シーンと起動シーンを変更できます。",
  "新项目组装": "新しいプロジェクト構成",
  "选择场景后审阅完整组装原文，再保存。": "シーンを選び、構成の原文全体を確認してから保存してください。",
  "组装已保存，可在构建目标中选择。": "構成を保存しました。ビルド対象として選択できます。",
  "工程目录已刷新；当前组装草稿已保留，请重新审阅。": "プロジェクト一覧を更新しました。構成の下書きは保持されています。再度確認してください。",
  "无法读取项目组装；当前草稿已保留。": "プロジェクト構成を読み込めません。下書きは保持されています。",
  "载入会替换当前组装草稿。继续吗？": "読み込むと現在の構成の下書きが置き換わります。続けますか？",
  "无法载入组装，请在原文编辑器修复；当前草稿已保留。": "構成を読み込めません。原文エディターで修正してください。下書きは保持されています。",
  "请核对成员顺序、启动场景与完整原文，再保存组装。": "シーンの順序、起動シーン、原文全体を確認してから保存してください。",
  "组装设置无效，请选择 1–32 个不同场景、有效启动场景和 JSON 保存位置。": "異なるシーンを 1～32 個、有効な起動シーン、JSON の保存先を選択してください。",
  "组装保存未完成；当前草稿已保留，请重新读取并审阅。": "構成を保存できませんでした。下書きは保持されています。読み直して確認してください。",
