  "{0} · 完成 {1}/{2} · 通过 {3} · 未通过 {4} · 未完成 {5} · 未运行 {6}": "{0} · 完了 {1}/{2} · 合格 {3} · 不合格 {4} · 未完了 {5} · 未実行 {6}",
