  "素材：{0}": "素材：{0}",
  "按原格式保存单个素材，不压缩、不转码。项目中的素材和编辑草稿保持不变。": "素材を元の形式で保存します。圧縮や変換は行いません。プロジェクト内の素材や編集中の下書きは変更されません。",
  "正在校验并准备原文件…": "元のファイルを検証して準備しています…",
