  "宿主尚未配置构建工具，可先检查计划。": "ホストにビルドツールが設定されていません。計画の検証は可能です。",
  "宿主配置的构建工具无法运行，请检查工具配置。": "設定されたビルドツールを実行できません。ホストのツール設定を確認してください。",
  "宿主配置的构建工具版本不受支持。": "設定されたビルドツールのバージョンには対応していません。",
  "构建后端的能力声明无效，请检查宿主配置。": "ビルドバックエンドの機能宣言が無効です。ホストの設定を確認してください。",
  "当前构建后端不支持此计划格式。": "現在のビルドバックエンドはこの計画形式に対応していません。",
