  "构建计划": "ビルド計画",
  "先检查计划，再构建。测试与预览使用最近成功构建的快照；编辑后需重新构建。无头测试不验证画面。": "計画を検証してからビルドします。テストとプレビューには直近の成功したビルドのスナップショットを使用するため、編集後は再ビルドが必要です。ヘッドレステストでは描画を検証しません。",
