  "当前保留 {0} 条原始运行事件摘要；内容见原始细节。": "現在、元の実行イベント要約を {0} 件保持しています。内容は元の詳細情報で確認できます。",
  "日志：保留 {0} / 共 {1} 个 UTF-16 代码单元，上限 {2}；较早部分已移出 {3} 个。": "ログ：全 {1} UTF-16 コード単位のうち {0} を保持（上限 {2}）。古い部分の {3} コード単位は保持対象外です。",
  "原始事件摘要：保留 {0} / 共 {1} 条，上限 {2}；已移出 {3} 条。此处不是项目事件账本。": "元のイベント要約：全 {1} 件のうち {0} 件を保持（上限 {2}）、{3} 件は保持対象外です。プロジェクトイベント台帳とは別の情報です。",
  "日志：留存信息不可用。": "ログ：保持情報を取得できません。",
  "原始事件摘要：留存信息不可用。此处不是项目事件账本。": "元のイベント要約：保持情報を取得できません。プロジェクトイベント台帳とは別の情報です。",
  "运行对象": "実行オブジェクト",
  "只读查看本次运行收到的对象状态。位置仅记录启动或结束样本，不代表实时坐标。": "今回の実行で受信したオブジェクトの状態を読み取り専用で表示します。位置は開始時または終了時のサンプルであり、現在の座標ではありません。",
