  "移动控制": "移動操作",
  "方向键": "矢印キー",
  "不接受输入": "入力なし",
  "移除场景对象": "シーンのオブジェクトを削除",
  "移除场景对象 {0}": "シーンのオブジェクト {0} を削除",
  "{0} · {1} 个对象引用 · {2} 个图片绑定": "{0} · オブジェクト参照 {1} 件 · 画像の割り当て {2} 件",
  "正在读取场景可用的对象与图片…": "シーンで利用できるオブジェクトと画像を読み込み中…",
  "配置场景后预览，确认原文与依赖再保存。": "シーンを設定してプレビューし、原文と依存関係を確認してから保存してください。",
  "无法读取工程，场景草稿保留，请重试。": "プロジェクトを読み込めません。シーンの下書きは保持されています。再試行してください。",
  "正在预览场景…": "シーンをプレビュー中…",
  "正在保存场景与依赖…": "シーンと依存関係を保存中…",
  "场景预览已就绪。确认后保存场景。": "シーンのプレビューができました。確認してから保存してください。",
  "场景已创建。返回构建面板检查计划并构建。": "シーンを作成しました。ビルドパネルに戻り、計画の検証とビルドを行ってください。",
  "场景已创建，但目录或构建列表刷新失败。请刷新核对，勿重复创建。": "シーンは作成されましたが、文書またはビルドの一覧を更新できませんでした。更新して確認してください。再度作成しないでください。",
  "场景请求未完成。草稿保留，请重新读取工程核对保存结果。": "シーンの要求が完了しませんでした。下書きは保持されています。プロジェクトを再読み込みして保存結果を確認してください。",
  "有未保存的场景设置，确定丢弃？": "シーンの未保存の設定を破棄しますか？",
  "暂无可构建场景。点击创建场景，选择已有对象开始。": "ビルド可能なシーンがありません。「シーンを作成」をクリックし、既存のオブジェクトを選択して始めてください。",
  "创建投影": "投影を作成",
  "同一份 OC 可拥有多个独立配置。来源正文保留在原对象中。": "1 つの OC に複数の独立した設定を作成できます。元の本文は元オブジェクトに保持されます。",
  "返回对象": "オブジェクトに戻る",
  "投影设置": "投影設定",
  "复用现有投影时，将当前配置展开为独立子模板快照；后续修改互不覆盖。图片需重新选择。": "既存の投影を再利用すると、現在の設定から独立したサブテンプレートを作成します。以後の変更は互いに反映されません。画像は再選択してください。",
  "投影配置": "投影の構成",
  "将创建的投影": "作成する投影",
  "预览投影": "投影をプレビュー",
  "保存投影": "投影を保存",
  "子模板": "サブテンプレート",
  "投影名称": "投影名",
  "复用投影：{0}": "投影を再利用：{0}",
  "来源对象：{0}": "元オブジェクト：{0}",
  "来源对象已不可用，请重新读取工程。": "元オブジェクトを利用できません。プロジェクトを再読み込みしてください。",
  "正在读取投影子模板与来源对象…": "投影サブテンプレートと元オブジェクトを読み込み中…",
  "{0}的投影": "{0} の投影",
  "配置投影后预览，确认来源与子模板再保存。": "投影を設定してプレビューし、元オブジェクトとサブテンプレートを確認してから保存してください。",
  "无法读取工程，投影草稿保留，请重试。": "プロジェクトを読み込めません。投影の下書きは保持されています。再試行してください。",
  "工程已变化。投影草稿保留，请重新读取工程并预览。": "プロジェクトが変更されました。投影の下書きは保持されています。再読み込みしてプレビューしてください。",
  "投影配置无效，请检查标出的位置。": "投影の設定が無効です。示された箇所を確認してください。",
  "正在预览投影…": "投影をプレビュー中…",
  "正在保存投影与来源关系…": "投影と元オブジェクトの関係を保存中…",
  "投影预览已就绪。确认后保存投影。": "投影のプレビューができました。確認後に保存してください。",
  "投影已创建，可返回对象查看或在兼容场景中选用。": "投影を作成しました。オブジェクトに戻って確認するか、対応するシーンで使用できます。",
  "投影已创建，但目录刷新失败。请刷新核对，勿重复创建。": "投影は作成されましたが、文書一覧を更新できませんでした。再作成せず、更新して確認してください。",
  "投影请求未完成。草稿保留，请重新读取工程核对保存结果。": "投影の処理が完了しませんでした。下書きは保持されています。プロジェクトを再読み込みして保存結果を確認してください。",
  "有未保存的投影设置，确定丢弃？": "未保存の投影設定を破棄しますか？",
  "返回来源对象：{0}": "元オブジェクトに戻る：{0}",
  "投影配置无效，请检查原文与诊断。": "投影の設定が無効です。原文と診断を確認してください。",
  "编辑投影原文": "投影の原文を開く",
  "此对象的投影": "このオブジェクトの投影",
  "暂无投影。可使用不同子模板创建独立配置。": "投影はまだありません。異なるサブテンプレートで独立した設定を作成できます。",
  "使用投影配置": "投影の設定を使用",
  "位置属于场景；图片、尺寸、颜色与控制继承投影。取消勾选可在此场景完整覆盖。": "位置はシーンに属します。画像、サイズ、色、操作は投影から継承します。チェックを外すと、このシーンで全設定を上書きできます。",
  "RPG 玩家角色": "RPG プレイヤーキャラクター",
