  "预期：{0}": "期待値：{0}",
  "实际：{0}": "実際の値：{0}",
  "验收结果不可读取，请刷新状态。": "検証結果を読み込めません。状態を更新してください。",
  "验收定义不是有效的 JSON，请检查后重试。": "検証定義が有効な JSON ではありません。確認して再試行してください。",
  "运行验收格式有误，请检查控制程序和预期检查。": "実行検証の形式が無効です。操作プログラムと期待値を確認してください。",
  "运行验收超出限制，请减少检查或控制步骤。": "実行検証が上限を超えています。チェックまたは操作ステップを減らしてください。",
  "运行验收仅支持无行为的第 2 版场景与有限无头控制回放。": "実行検証には、ユーザー定義動作のない第 2 版のシーンと、有限ヘッドレス操作リプレイが必要です。",
  "验收引用的实例不属于当前构建，请核对实例标识。": "検証が参照するインスタンスは現在のビルドにありません。識別子を確認してください。",
  "运行验收收到无效样本，请查看原始日志。": "実行検証で無効なサンプルを受信しました。元のログを確認してください。",
  "查看用例详情": "用例の詳細を表示",
  "用例验收详情": "用例の検証詳細",
  "关闭用例详情": "用例の詳細を閉じる",
  "这是本批次已完成成员的只读报告。导出保留捕获的定义和采样，不会更新用例或生成新的预期。": "現在のバッチで完了した用例の読み取り専用レポートです。書き出しには取得済みの定義とサンプルが含まれ、用例の更新や期待値の生成は行いません。",
  "导出用例报告 JSON": "用例レポートを JSON で書き出す",
  "此批次已不是当前任务，请查看当前批次成员。": "このバッチは現在のタスクではありません。現在のバッチの用例を確認してください。",
  "此用例报告尚未就绪，请等待成员完成后重试。": "用例レポートはまだ準備できていません。用例の完了後に再試行してください。",
  "此用例报告已变化，请刷新状态后重新查看。": "用例レポートが変わりました。状態を更新してから再度確認してください。",
  "此用例报告不可读取，请刷新状态后重试。": "用例レポートを読み取れません。状態を更新してから再試行してください。",
  "用例报告格式或评价不一致，无法显示或导出。": "用例レポートの形式または評価に不整合があり、表示や書き出しができません。",
  "用例报告超出读取限制，无法显示或导出。": "用例レポートが読み取り上限を超えており、表示や書き出しができません。",
  "正在读取用例报告…": "用例レポートを読み取り中…",
