  "第 {0} / {1} 处匹配": "{1}件中{0}件目の一致",
  "匹配数量或替换结果超出限制，请缩小查找范围。": "一致件数または置換結果が上限を超えています。検索範囲を絞ってください。",
  "当前文本或查找内容超出支持范围。": "原文または検索内容が対応範囲を超えています。",
  "替换内容与原文相同，未修改。": "置換内容が原文と同じため、変更はありません。",
  "请先选中一处匹配文本。": "先に一致する文字列を選択してください。",
  "当前浏览器无法保留撤销记录，未执行替换。": "このブラウザーでは元に戻す履歴を保持できないため、置換しませんでした。",
  "已替换 {0} 处；请按普通流程保存。": "{0}件を置換しました。通常どおりエディターで保存してください。",
  "替换未能完整应用，请检查原文或撤销后重试。": "置換を完全に適用できませんでした。原文を確認するか、元に戻して再試行してください。",
