  "用当前场景创建组装": "現在のシーンからプロジェクトを構成",
  "逐实例动画需要项目组装。请用当前场景创建组装后，再检查计划和构建。": "インスタンスごとのアニメーションにはプロジェクト構成が必要です。現在のシーンから構成を作成し、プランを確認してビルドしてください。",
  "{0} 的项目组装": "{0} のプロジェクト構成",
  "已将当前场景设为首个成员和启动场景，请审阅后保存组装。": "現在のシーンを最初のメンバーと開始シーンに設定しました。内容を確認して構成を保存してください。",
  "当前场景不在已保存的二维场景目录中，请先保存场景后重新打开组装。": "現在のシーンは保存済み2Dシーンの一覧にありません。シーンを保存してから構成を開き直してください。",
  "当前作者状态已变化，请返回后重新打开组装。": "編集状態が変わりました。戻ってから構成を開き直してください。",

  "编辑二维物理": "2D 物理を編集",
  "物理声明参数": "物理宣言のパラメーター",
  "编辑已有物理声明，检查后应用到原文草稿。": "既存の物理宣言を編集し、検証してからソースの下書きに適用します。",
  "这里只检查声明参数；场景成员、控制方式和登记关系由工程预检检查。": "ここでは宣言のパラメーターを検証します。シーンの所属、移動の操作設定、登録関係はプロジェクトの事前検証で確認します。",
  "物理所属场景：{0}": "物理宣言のシーン：{0}",
  "碰撞体": "物理ボディ",
  "碰撞体 {0}": "ボディ {0}",
