  "实例编号": "インスタンス ID",
  "手动填写已有场景实例的编号；不会新建或修改场景实例。": "既存のシーンインスタンス ID を入力してください。シーンインスタンスの作成や変更は行いません。",
  "物理类型": "ボディの種類",
