  "层与掩码均为 0–65535；按位组合 16 个碰撞层。": "レイヤーとマスクは 0〜65535。16 個の衝突レイヤーをビットマスクで組み合わせます。",
  "添加碰撞体": "ボディを追加",
  "移除碰撞体": "ボディを削除",
  "物理形状示意": "衝突形状の図",
  "局部坐标示意；不运行碰撞，也不表示场景中的位置。": "ローカル座標での図です。衝突シミュレーションやシーン内の位置を示すものではありません。",
  "检查当前表单后显示形状示意。": "現在のフォームを検証すると形状の図を表示します。",
