  "丢弃本次物理表单修改？原文草稿不会改变。": "今回の物理フォームの変更を破棄しますか？ソースの下書きは変更されません。",
  "正在读取物理文档…": "物理ドキュメントを読み込み中…",
  "无法读取有效物理文档，请检查原文。": "有効な物理ドキュメントを読み込めません。ソースを確認してください。",
  "物理表单已变化；检查后可预览并应用。": "物理フォームが変更されました。検証してからプレビューや適用を行ってください。",
  "正在检查物理修改…": "物理変更を検証中…",
  "物理参数已检查，请审阅完整原文后应用。": "物理パラメーターを検証しました。ソース全体を確認してから適用してください。",
  "物理参数已检查；未修改原文。": "物理パラメーターを検証しました。ソースは変更していません。",
  "物理修改未通过检查，输入已保留。": "物理変更の検証に失敗しました。入力内容は保持しています。",
  "正在应用物理修改到原文草稿…": "物理変更をソースの下書きに適用中…",
  "物理修改未确认应用，输入已保留。": "物理変更の適用を確認できませんでした。入力内容は保持しています。",
  "原文已变化，请返回后重新打开物理编辑。": "ソースが変更されました。戻って物理エディターを開き直してください。",
  "无法分配新的碰撞体编号，输入已保留。": "新しいボディ ID を割り当てられませんでした。入力内容は保持しています。",
  "物理修改已应用到原文草稿；尚未保存。": "物理変更をソースの下書きに適用しました。まだ保存していません。",
  "物理修改已应用；文本与已保存版本一致。": "物理変更を適用しました。テキストは保存済みの内容と一致しています。",
  "丢弃本次二维物理创建设置？已保存的物理与关系会保留。": "今回の2D物理の作成設定を破棄しますか？保存済みの物理と関連付けは保持されます。",
  "为已保存的二维场景创建第一个物理体。选择场景实例和形状，审阅完整原文与关系后保存。保存后可继续使用二维物理字段编辑器。": "保存済みの2Dシーンに最初の物理ボディを作成します。インスタンスと形状を選び、ソース全体と関連付けを確認して保存してください。保存後は2D物理フィールドエディターで編集できます。",
  "二维物理与关系已确认保存。可打开原文继续编辑。": "2D物理と関連付けの保存を確認しました。ソースを開いて編集を続けられます。",
  "二维物理保存结果尚未确认，请重新读取工程核对，勿重复创建。": "2D物理の保存結果を確認できていません。重複作成せず、プロジェクトを再読み込みして確認してください。",
  "二维物理创建已审阅，请确认完整原文和双向关系后保存。": "2D物理の作成内容を確認しました。ソース全体と双方向の関連付けを確認して保存してください。",
  "二维物理原文未打开，请重新读取工程后重试。": "2D物理のソースを開けませんでした。プロジェクトを再読み込みして再試行してください。",
  "二维物理尚未保存，请先审阅原文和双向关系。": "2D物理はまだ保存されていません。まずソースと双方向の関連付けを確認してください。",
  "二维物理文档或关系已变化，请确认目录后重新打开原文。": "2D物理の文書または関連付けが変更されました。一覧を確認してソースを開き直してください。",
  "二维物理请求未完成。设置已保留，请重新读取并审阅。": "2D物理のリクエストが完了しませんでした。設定は保持されています。再読み込みして確認してください。",
  "传感器物理体": "センサーボディ",
  "保存会新建二维物理正文和登记，并更新场景的 physics2d 关系；场景正文和素材字节保持。": "保存すると2D物理のソースと登録を作成し、シーンの physics2d 関連付けを更新します。シーンのソースと素材データは保持されます。",
  "保存物理与关系": "物理と関連付けを保存",
  "圆形半径": "円の半径",
  "场景二维物理": "シーンの2D物理",
  "场景已有关联二维物理": "シーンには2D物理が関連付けられています",
  "场景暂无可绑定物理体的实例。请先保存场景实例，再重新读取工程。": "物理ボディを設定できるインスタンスがありません。先にシーンのインスタンスを保存し、プロジェクトを再読み込みしてください。",
  "审阅二维物理": "2D物理を確認",
  "已有二维物理文档不会重复创建。打开原文后，可使用独立物理字段编辑器。": "既存の2D物理文書を使用します。ソースを開くと物理フィールドエディターを利用できます。",
  "打开二维物理原文": "2D物理ソースを開く",
  "新二维物理文档": "新しい2D物理文書",
  "新二维物理文档审阅": "新しい2D物理文書の確認",
  "新文档身份：{0} · 物理体身份：{1}": "新しい文書ID：{0} · ボディID：{1}",
  "无法读取二维物理目录。设置已保留，请检查关系并重试。": "2D物理の一覧を読み込めません。設定は保持されています。関連付けを確認して再試行してください。",
  "来源或会话已变化，请返回构建后重新打开二维物理设置。": "ソースまたはセッションが変更されました。ビルドに戻り、2D物理設定を開き直してください。",
  "正在保存二维物理文档与关系…": "2D物理文書と関連付けを保存中…",
  "正在审阅二维物理文档与关系…": "2D物理文書と関連付けを確認中…",
  "正在核对二维物理原文…": "2D物理ソースを照合中…",
