  "此场景已有二维物理文档，可打开原文继续编辑。": "このシーンには2D物理文書があります。ソースを開いて編集を続けられます。",
  "物理体类型": "ボディの種類",
  "物理设置无效，请检查形状尺寸、偏移、层和检测掩码。": "物理設定が無効です。形状の寸法、オフセット、レイヤー、検出マスクを確認してください。",
  "矩形宽度": "矩形の幅",
  "矩形宽高 1–8192，圆形半径 0.5–4096，偏移 ±8192，层与检测掩码为 0–65535 的整数。目录来自已保存场景，不包含草稿。": "矩形の幅・高さ：1～8192、円の半径：0.5～4096、オフセット：±8192、レイヤー・検出マスク：0～65535の整数。一覧は保存済みシーンに基づき、下書きは含みません。",
  "矩形高度": "矩形の高さ",
  "碰撞偏移 X": "衝突オフセット X",
  "碰撞偏移 Y": "衝突オフセット Y",
  "碰撞层位掩码": "衝突レイヤーのビットマスク",
  "碰撞检测位掩码": "衝突検出のビットマスク",
  "角色物理体": "キャラクターボディ",
  "请选择有效的物理体类型和碰撞形状。": "有効なボディの種類と衝突形状を選択してください。",
  "选择场景实例与物理体设置，审阅后保存二维物理文档。": "シーンのインスタンスとボディ設定を選び、確認して2D物理文書を保存してください。",
  "静态体和传感器要求场景实例的有效控制为 none、速度为 0；工程构建预检会验证运动条件。此处不会修改场景运动设置。": "静的ボディとセンサーには、シーンインスタンスの有効な操作設定 none と速度 0 が必要です。ビルド事前検証で移動条件を確認します。この画面ではシーンの移動設定を保持します。",
  "静态物理体": "静的ボディ",
  "场景物理": "シーン物理",
  "核对场景物理": "シーン物理を照合",
  "物理声明已保存，但目录刷新失败。请重新读取工程，勿重复创建。": "物理宣言は保存されましたが、一覧を更新できませんでした。重複作成せず、プロジェクトを再読み込みしてください。",
  "{0} · {1} · 实例 {2} · 碰撞体 {3}": "{0} · {1} · インスタンス {2} · 衝突体 {3}",
  "{0} 个碰撞体的目标已不在场景中；保留声明，可选择后修正实例编号。": "{0} 個の衝突体の対象がシーンにありません。宣言は保持されています。衝突体を選択してインスタンス ID を修正してください。",
  "以已保存场景的位置显示检查过的物理参数；浅色框为实例逻辑尺寸。点击形状或列表选择碰撞体，不运行碰撞模拟。": "確認済みの物理パラメーターを保存済みシーンの位置に表示します。薄い枠はインスタンスの論理サイズです。形状または一覧をクリックして衝突体を選択できます。衝突シミュレーションは行いません。",
  "刷新场景位置": "シーンの位置を再読み込み",
  "场景中的碰撞形状": "シーン内の衝突形状",
  "场景碰撞形状：{0}": "シーンの衝突形状：{0}",
  "尚未读取场景位置；字段编辑和局部形状示意仍可使用。": "シーンの位置はまだ読み込まれていません。フィールド編集とローカル形状図は引き続き使用できます。",
  "已显示 {0} 个碰撞体；场景草稿不包含在此视图中。": "{0} 個の衝突体を表示しています。シーンの未保存の下書きは含まれません。",
  "无法显示场景位置；字段编辑仍可使用，可刷新重试。": "シーンの位置を表示できません。フィールド編集は引き続き使用できます。再読み込みしてお試しください。",
  "正在读取已保存场景的位置…": "保存済みシーンの位置を読み込み中…",
  "目标缺失 · {0} · 实例 {1} · 碰撞体 {2}": "対象なし · {0} · インスタンス {1} · 衝突体 {2}",
  "表单有未检查的修改；检查后显示场景中的碰撞形状。": "フォームに未確認の変更があります。確認後にシーン内の衝突形状を表示します。",
  "选择场景中的碰撞体": "シーン内の衝突体を選択",
  "读取场景空间": "シーン配置を読み込み",
  "向上调整偏移": "オフセットを上へ移動",
  "向下调整偏移": "オフセットを下へ移動",
